SET NAMES utf8mb4;
CREATE TEMPORARY TABLE cover_repair_map (recipe_id varchar(36) PRIMARY KEY, old_path varchar(255) NOT NULL, new_path varchar(255) NOT NULL);
INSERT INTO cover_repair_map VALUES (CONVERT(0x6465616435393336316337613434613761356436613666643935363734393464 USING utf8mb4),CONVERT(0x7265636970652f636f7665722f6f7074696d697a65642d32303236313033302f37326638623038622d336133372d343664632d613666362d3562333230363338353732332e77656270 USING utf8mb4),CONVERT(0x7265636970652f636f7665722f37326638623038622d336133372d343664632d613666362d3562333230363338353732332e77656270 USING utf8mb4));
