INSERT INTO cover_repair_map VALUES (CONVERT(0x6633663734303934633338303464656462653638323266666333353232343430 USING utf8mb4),CONVERT(0x7265636970652f636f7665722f6f7074696d697a65642d32303236313033302f62303061303430662d306337322d343632632d396265362d3031373532373830613865392e77656270 USING utf8mb4),CONVERT(0x7265636970652f636f7665722f62303061303430662d306337322d343632632d396265362d3031373532373830613865392e77656270 USING utf8mb4));
START TRANSACTION;
UPDATE recipe r JOIN cover_repair_map m ON CAST(r.id AS BINARY)=CAST(m.recipe_id AS BINARY) SET r.cover_image=m.new_path,r.update_time=NOW() WHERE CAST(r.cover_image AS BINARY) IN (CAST(m.old_path AS BINARY), CAST(CONCAT('/',m.old_path) AS BINARY), CAST(CONCAT(CONVERT(0x68747470733a2f2f77672d7265636970652d313338353639363536332e636f732e61702d6368656e6764752e6d7971636c6f75642e636f6d2f USING utf8mb4),m.old_path) AS BINARY));
UPDATE user_favorite t JOIN cover_repair_map m ON CAST(t.recipe_id AS BINARY)=CAST(m.recipe_id AS BINARY) JOIN recipe r ON CAST(r.id AS BINARY)=CAST(m.recipe_id AS BINARY) AND CAST(r.cover_image AS BINARY)=CAST(m.new_path AS BINARY) SET t.cover_image=m.new_path,t.update_time=NOW() WHERE CAST(t.cover_image AS BINARY) IN (CAST(m.old_path AS BINARY), CAST(CONCAT('/',m.old_path) AS BINARY), CAST(CONCAT(CONVERT(0x68747470733a2f2f77672d7265636970652d313338353639363536332e636f732e61702d6368656e6764752e6d7971636c6f75642e636f6d2f USING utf8mb4),m.old_path) AS BINARY));
UPDATE user_wanted_recipe t JOIN cover_repair_map m ON CAST(t.recipe_id AS BINARY)=CAST(m.recipe_id AS BINARY) JOIN recipe r ON CAST(r.id AS BINARY)=CAST(m.recipe_id AS BINARY) AND CAST(r.cover_image AS BINARY)=CAST(m.new_path AS BINARY) SET t.cover_image=m.new_path,t.update_time=NOW() WHERE CAST(t.cover_image AS BINARY) IN (CAST(m.old_path AS BINARY), CAST(CONCAT('/',m.old_path) AS BINARY), CAST(CONCAT(CONVERT(0x68747470733a2f2f77672d7265636970652d313338353639363536332e636f732e61702d6368656e6764752e6d7971636c6f75642e636f6d2f USING utf8mb4),m.old_path) AS BINARY));
UPDATE recipe_image t JOIN cover_repair_map m ON CAST(t.recipe_id AS BINARY)=CAST(m.recipe_id AS BINARY) JOIN recipe r ON CAST(r.id AS BINARY)=CAST(m.recipe_id AS BINARY) AND CAST(r.cover_image AS BINARY)=CAST(m.new_path AS BINARY) SET t.image_url=m.new_path,t.update_time=NOW() WHERE CAST(t.image_url AS BINARY) IN (CAST(m.old_path AS BINARY), CAST(CONCAT('/',m.old_path) AS BINARY), CAST(CONCAT(CONVERT(0x68747470733a2f2f77672d7265636970652d313338353639363536332e636f732e61702d6368656e6764752e6d7971636c6f75642e636f6d2f USING utf8mb4),m.old_path) AS BINARY));
UPDATE recipe_step t JOIN cover_repair_map m ON CAST(t.recipe_id AS BINARY)=CAST(m.recipe_id AS BINARY) JOIN recipe r ON CAST(r.id AS BINARY)=CAST(m.recipe_id AS BINARY) AND CAST(r.cover_image AS BINARY)=CAST(m.new_path AS BINARY) SET t.step_image=m.new_path,t.update_time=NOW() WHERE CAST(t.step_image AS BINARY) IN (CAST(m.old_path AS BINARY), CAST(CONCAT('/',m.old_path) AS BINARY), CAST(CONCAT(CONVERT(0x68747470733a2f2f77672d7265636970652d313338353639363536332e636f732e61702d6368656e6764752e6d7971636c6f75642e636f6d2f USING utf8mb4),m.old_path) AS BINARY));
COMMIT;
SELECT COUNT(*) AS mapped_recipes FROM recipe r JOIN cover_repair_map m ON CAST(r.id AS BINARY)=CAST(m.recipe_id AS BINARY) AND CAST(r.cover_image AS BINARY)=CAST(m.new_path AS BINARY);
